$$('[data-workspace-tab]').forEach(b=>b.addEventListener('click',()=>{const tab=b.dataset.workspaceTab;setWorkspaceTab(tab);requestAnimationFrame(()=>{const target=tab==='strategy'?$('.game-layout'):$(`[data-workspace="${tab}"].active`);if(target){target.style.scrollMarginTop=(window.innerWidth>900?$('.workspace-nav').offsetHeight+20:12)+'px';target.scrollIntoView({block:'start',behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'})}})}));$$('.mode').forEach(b=>b.addEventListener('click',()=>setMode(b.dataset.mode)));$('#startAi').addEventListener('click',()=>startLocal('ai'));$('#startHotseat').addEventListener('click',()=>startLocal('hotseat'));$('#createLan').addEventListener('click',createLanRoom);$('#joinLan').addEventListener('click',joinLanRoom);$('#continueBtn').addEventListener('click',continueSave);$('#importBtn').addEventListener('click',()=>$('#importFile').click());$('#importFile').addEventListener('change',e=>{if(e.target.files[0])importSave(e.target.files[0])});$('#ghCreate').addEventListener('click',ghCreateRoom);$('#ghJoin').addEventListener('click',ghJoinRoom);$('#ghForget').addEventListener('click',ghForget);$('#ghResume').addEventListener('click',ghResume);$('#makeOffer').addEventListener('click',()=>createOffer(false));$('#makeAnswer').addEventListener('click',()=>{const again=relinking;relinking=false;createAnswer(again)});$('#relinkBtn').addEventListener('click',()=>{if(gh.active){ghRetry();return}if(p2pRole==='host')createOffer(true);else startRejoin()});$('#rejoinBtn').addEventListener('click',startRejoin);$('#applyAnswer').addEventListener('click',applyAnswer);$('#copyCode').addEventListener('click',copyCode);$('#cancelConnect').addEventListener('click',()=>{if(game||view){relinking=false;show('#gameScreen');render()}else leaveGame()});$('#readyBtn').addEventListener('click',submitPlan);$('#recallBtn').addEventListener('click',recallPlan);$('#exportBtn').addEventListener('click',exportSave);$('#exitBtn').addEventListener('click',leaveGame);$('#closeGameBtn').addEventListener('click',leaveGame);$('#rematchBtn').addEventListener('click',requestRematch);$('#resolutionContinue').addEventListener('click',()=>{$('#resolutionScreen').classList.add('hidden');const v=currentView();if(v&&v.gameOver)renderFinal(v)});$('#privacyContinue').addEventListener('click',()=>{if(privacyNext){const fn=privacyNext;privacyNext=null;fn()}});window.addEventListener('beforeunload',()=>{ghCheckpoint();if(game&&(['ai','hotseat'].includes(game.mode)||(game.mode==='lan'&&p2pRole==='host')))saveLocal()});loadLanIp();ghRestore();updateContinue();setMode('ai');
